"""Tests for the autogenerated API docs page."""
from __future__ import annotations

from dataclasses import replace
from unittest.mock import MagicMock, patch

import pytest
from fastapi.testclient import TestClient


@pytest.fixture()
def authed_client(monkeypatch):
    """TestClient logged in via the session cookie flow."""
    import app.main as main_mod
    import app.routers.auth as auth_mod
    from app.config import settings

    patched = replace(settings, password="test-pw")
    monkeypatch.setattr(main_mod, "settings", patched)
    monkeypatch.setattr(auth_mod, "settings", patched)

    # https base URL — the session cookie is Secure by default and would be
    # dropped by the client over plain http.
    with TestClient(
        main_mod.app, base_url="https://testserver", raise_server_exceptions=True
    ) as c:
        resp = c.post(
            f"{settings.root_path}/login",
            data={"password": "test-pw"},
            follow_redirects=False,
        )
        # success redirects; a 200 means the login form re-rendered with an error
        assert resp.status_code in (302, 303), resp.text
        yield c


def _docs_path() -> str:
    from app.config import settings
    return f"{settings.root_path}/api-docs"


def _mock_llama_swap(model_ids):
    """Mock httpx.Client so the handler sees a live llama-swap model list."""
    fake_resp = MagicMock()
    fake_resp.json.return_value = {"data": [{"id": m} for m in model_ids]}
    fake_resp.raise_for_status.return_value = None
    fake_client = MagicMock()
    fake_client.__enter__.return_value.get.return_value = fake_resp
    fake_client.__exit__.return_value = False
    return patch("httpx.Client", return_value=fake_client)


def test_api_docs_renders_live_data(authed_client):
    """Model count, example model and voices come from live sources."""
    with _mock_llama_swap(["gemma-x", "gufo-ornith-1.5-q6dense", "other-model"]), \
         patch("app.tts.list_voices", return_value=["cs_CZ-jirka-medium", "en_US-ryan-medium"]):
        resp = authed_client.get(_docs_path())

    assert resp.status_code == 200
    body = resp.text
    # live model count + example model preference for the everyday default
    assert "3 models" in body
    assert '"model": "gufo-ornith-1.5-q6dense"' in body
    # voices count + example voice
    assert "2</strong> currently installed" in body
    assert "cs_CZ-jirka-medium" in body
    # LLM public base from config
    assert "/llm/v1" in body


def test_api_docs_endpoint_table_autogenerated(authed_client):
    """Audio + api-keys routes appear in the generated endpoint table."""
    from app.config import settings

    with _mock_llama_swap(["m1"]), \
         patch("app.tts.list_voices", return_value=[]):
        resp = authed_client.get(_docs_path())

    assert resp.status_code == 200
    body = resp.text
    root = settings.root_path
    for path in (
        f"{root}/api/v1/audio/speech",
        f"{root}/api/v1/audio/transcriptions",
        f"{root}/api/v1/audio/voices",
        f"{root}/api/v1/audio/install",
        f"{root}/api/keys",
    ):
        assert path in body, f"missing autogenerated endpoint: {path}"
    # public/session auth badges present
    assert "public*" in body
    assert "session" in body


def test_api_docs_degrades_when_llama_swap_down(authed_client):
    """Page still renders (200) when llama-swap is unreachable."""
    import httpx

    with patch("httpx.Client", side_effect=httpx.ConnectError("down")), \
         patch("app.tts.list_voices", return_value=[]):
        resp = authed_client.get(_docs_path())

    assert resp.status_code == 200
    assert "llama-swap unreachable" in resp.text
    # falls back to the static example model
    assert '"model": "gufo-ornith-1.5-q6dense"' in resp.text
    # NPU section still renders, flagged as not answering
    assert "halogen is not loaded" in resp.text


def test_api_docs_example_model_falls_back_to_first_live_model(authed_client):
    """Without a preferred model in the live list the first one is shown."""
    with _mock_llama_swap(["aaa-model", "zzz-model"]), \
         patch("app.tts.list_voices", return_value=[]):
        resp = authed_client.get(_docs_path())
    assert '"model": "aaa-model"' in resp.text


def test_api_docs_npu_section_shows_live_models(authed_client):
    """With halogen up, the NPU section lists its models and the direct port."""
    from app.config import settings

    fake_resp = MagicMock()
    fake_resp.raise_for_status.return_value = None
    fake_resp.json.return_value = {
        "data": [{"id": "halogen-flash-next"}],
        "npu": {"status": "ok", "models": ["decider-0.8b", "qwen3-embedding-0.6b"]},
    }
    fake_client = MagicMock()
    fake_client.__enter__.return_value.get.return_value = fake_resp
    fake_client.__exit__.return_value = False
    with patch("httpx.Client", return_value=fake_client), \
         patch("app.tts.list_voices", return_value=[]):
        resp = authed_client.get(_docs_path())

    body = resp.text
    assert resp.status_code == 200
    assert "NPU up right now" in body
    assert "decider-0.8b, qwen3-embedding-0.6b" in body
    assert f"{settings.npu_lan_base}/v1/systemone" in body
    assert "halogen is not loaded" not in body
